import re

def parse(lines):
    blocks = []
    skip = []
    cur = None
    last = None
    n = len(lines)
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if re.match(r'^-{3,}\s*$', l):
            skip.append(i)
            continue
        if i + 1 < n and re.match(r'^-{3,}\s*$', lines[i + 1]) and not l[:1].isspace():
            title = l.strip()
            cur = {'name': title, 'kind': 'kv', 'lines': [i], 'records': [{'entry type': title}]}
            blocks.append(cur)
            last = None
            continue
        if l[:1].isspace():
            if cur is not None and last is not None:
                rec = cur['records'][0]
                rec[last] = rec[last] + ', ' + l.strip()
                cur['lines'].append(i)
            continue
        m = re.match(r'^(?P<key>\S+)\s+(?P<value>\S.*?)\s*$', l)
        if m:
            if cur is None:
                cur = {'name': 'entry', 'kind': 'kv', 'lines': [], 'records': [{}]}
                blocks.append(cur)
            cur['records'][0][m.group('key')] = m.group('value')
            cur['lines'].append(i)
            last = m.group('key')
    return {'blocks': blocks, 'skip': skip}
